-- Structured 30-item career-interest inventory for counseling conversations.
-- This is not a licensed/validated psychometric instrument. Do not use for admission decisions.
BEGIN;

-- Retire the original eight-item demo inventory when this migration is applied.
UPDATE public.aptitude_questions
SET is_active = false
WHERE question_key LIKE 'interest-%' AND is_active = true;

ON CONFLICT (question_key, version) DO UPDATE
SET question_text = EXCLUDED.question_text,
    options = EXCLUDED.options,
    scoring_rubric = EXCLUDED.scoring_rubric,
    skill_dimension = EXCLUDED.skill_dimension,
    is_active = true;

COMMIT;
